-- =============================================================
-- sharding-demo init script (2 databases x 4 tables, gene sharding)
-- MySQL 5.7+ / 8.0
--
-- Design (mini copy of the 'gene method' sharding in resume):
--   logic table    : t_order
--   physical layout: databases shard_order_0 / shard_order_1
--                    each database holds t_order_0 ~ t_order_3
--   table shard key: order_number / user_id
--   order_number is generated by app (snowflake-like), low log2(4)=2 bits
--                    carry the gene: userId % 4
--   table route    : tableIndex = order_number & 3  == userId % 4
--   database route : hash the tail 2 gene bits, then & 1 -> db 0 or 1
--   effect         : querying by order_number OR user_id hits the same
--                    database and the same table (no read diffusion)
-- =============================================================

CREATE DATABASE IF NOT EXISTS shard_order_0 DEFAULT CHARACTER SET utf8mb4;
CREATE DATABASE IF NOT EXISTS shard_order_1 DEFAULT CHARACTER SET utf8mb4;

-- ---------------- shard_order_0 ----------------
USE shard_order_0;

CREATE TABLE IF NOT EXISTS t_order_0 (
    order_number BIGINT        NOT NULL,
    user_id      BIGINT        NOT NULL,
    program_id   BIGINT        NOT NULL,
    order_price  DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    order_status TINYINT       NOT NULL DEFAULT 1,
    create_time  DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    edit_time    DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (order_number),
    KEY idx_user_id (user_id),
    KEY idx_program_id (program_id)
) ENGINE = InnoDB COMMENT = 'order table 0';

CREATE TABLE IF NOT EXISTS t_order_1 (
    order_number BIGINT        NOT NULL,
    user_id      BIGINT        NOT NULL,
    program_id   BIGINT        NOT NULL,
    order_price  DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    order_status TINYINT       NOT NULL DEFAULT 1,
    create_time  DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    edit_time    DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (order_number),
    KEY idx_user_id (user_id),
    KEY idx_program_id (program_id)
) ENGINE = InnoDB COMMENT = 'order table 1';

CREATE TABLE IF NOT EXISTS t_order_2 (
    order_number BIGINT        NOT NULL,
    user_id      BIGINT        NOT NULL,
    program_id   BIGINT        NOT NULL,
    order_price  DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    order_status TINYINT       NOT NULL DEFAULT 1,
    create_time  DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    edit_time    DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (order_number),
    KEY idx_user_id (user_id),
    KEY idx_program_id (program_id)
) ENGINE = InnoDB COMMENT = 'order table 2';

CREATE TABLE IF NOT EXISTS t_order_3 (
    order_number BIGINT        NOT NULL,
    user_id      BIGINT        NOT NULL,
    program_id   BIGINT        NOT NULL,
    order_price  DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    order_status TINYINT       NOT NULL DEFAULT 1,
    create_time  DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    edit_time    DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (order_number),
    KEY idx_user_id (user_id),
    KEY idx_program_id (program_id)
) ENGINE = InnoDB COMMENT = 'order table 3';

-- ---------------- shard_order_1 ----------------
USE shard_order_1;

CREATE TABLE IF NOT EXISTS t_order_0 (
    order_number BIGINT        NOT NULL,
    user_id      BIGINT        NOT NULL,
    program_id   BIGINT        NOT NULL,
    order_price  DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    order_status TINYINT       NOT NULL DEFAULT 1,
    create_time  DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    edit_time    DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (order_number),
    KEY idx_user_id (user_id),
    KEY idx_program_id (program_id)
) ENGINE = InnoDB COMMENT = 'order table 0';

CREATE TABLE IF NOT EXISTS t_order_1 (
    order_number BIGINT        NOT NULL,
    user_id      BIGINT        NOT NULL,
    program_id   BIGINT        NOT NULL,
    order_price  DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    order_status TINYINT       NOT NULL DEFAULT 1,
    create_time  DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    edit_time    DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (order_number),
    KEY idx_user_id (user_id),
    KEY idx_program_id (program_id)
) ENGINE = InnoDB COMMENT = 'order table 1';

CREATE TABLE IF NOT EXISTS t_order_2 (
    order_number BIGINT        NOT NULL,
    user_id      BIGINT        NOT NULL,
    program_id   BIGINT        NOT NULL,
    order_price  DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    order_status TINYINT       NOT NULL DEFAULT 1,
    create_time  DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    edit_time    DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (order_number),
    KEY idx_user_id (user_id),
    KEY idx_program_id (program_id)
) ENGINE = InnoDB COMMENT = 'order table 2';

CREATE TABLE IF NOT EXISTS t_order_3 (
    order_number BIGINT        NOT NULL,
    user_id      BIGINT        NOT NULL,
    program_id   BIGINT        NOT NULL,
    order_price  DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    order_status TINYINT       NOT NULL DEFAULT 1,
    create_time  DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    edit_time    DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (order_number),
    KEY idx_user_id (user_id),
    KEY idx_program_id (program_id)
) ENGINE = InnoDB COMMENT = 'order table 3';

-- NOTE: app-side order_number generation (implemented in Java later)
--   (snowflake << 2) | (userId % 4)  -> embed userId gene in low bits
